import{_ as t,o,c as a,ag as s}from"./chunks/framework.8tqBsFWt.js";const u=JSON.parse('{"title":"Unresolved items sweep","description":"","frontmatter":{},"headers":[],"relativePath":"playbook/unresolved-items-sweep.md","filePath":"playbook/unresolved-items-sweep.md"}'),n={name:"playbook/unresolved-items-sweep.md"};function i(r,e,l,h,d,c){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="unresolved-items-sweep" tabindex="-1">Unresolved items sweep <a class="header-anchor" href="#unresolved-items-sweep" aria-label="Permalink to &quot;Unresolved items sweep&quot;">​</a></h1><p><strong>Cadence</strong>: Ad hoc (ideally weekly) · <strong>Who</strong>: Managers and Owners</p><h2 id="situation" tabindex="-1">Situation <a class="header-anchor" href="#situation" aria-label="Permalink to &quot;Situation&quot;">​</a></h2><p>Things pile up. Ambiguous time entries nobody&#39;s classified. PTO requests that never got approved. Projects sitting in a state that needs a decision. This play clears the backlog — one list, everything waiting on you or your team.</p><h2 id="in-the-console" tabindex="-1">In the console <a class="header-anchor" href="#in-the-console" aria-label="Permalink to &quot;In the console&quot;">​</a></h2><p>Open <strong>Unresolved</strong> (<code>/console/unresolved</code>). Everything waiting on a decision in one queue, each item with its resolve/dismiss options inline. Oldest first, so the dusty items surface.</p><h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2><p>Items grouped by type:</p><ul><li><strong>Pending PTO</strong> — who, when, how many hours</li><li><strong>Ambiguous time entries</strong> — what the person said, what VERA couldn&#39;t match</li><li><strong>Stuck project status</strong> — projects awaiting a decision (e.g. over-budget with no scope change recorded)</li><li><strong>Missing allocations</strong> — active projects with nobody allocated, or team members logging time to projects they have no envelope on</li></ul><p>Each item shows:</p><p><code>#ID — description · raised by · raised when · options to resolve</code></p><p>Sorted: oldest first, so the dusty items surface.</p><h2 id="who-can-run-it" tabindex="-1">Who can run it <a class="header-anchor" href="#who-can-run-it" aria-label="Permalink to &quot;Who can run it&quot;">​</a></h2><p>Managers and Owners. Managers see items they can act on — pending PTO for their team, stuck projects under their management, etc.</p><h2 id="related-plays" tabindex="-1">Related plays <a class="header-anchor" href="#related-plays" aria-label="Permalink to &quot;Related plays&quot;">​</a></h2><ul><li><a href="./ooo-coordination.html">OOO coordination for the week ahead</a> — the PTO slice of this view</li><li><a href="./project-health-probe.html">Project health probe</a> — drill into any flagged project</li></ul>',16)])])}const m=t(n,[["render",i]]);export{u as __pageData,m as default};
